import { Language } from '@/contexts/LanguageContext';

// Bilingual text entries for BNN content
// For Hindi: direct translation, For other languages: "English (Translation)"
export interface BilingualEntry {
  en: string;
  hi: string;
  mr?: string;
  bn?: string;
  te?: string;
  ta?: string;
  gu?: string;
  kn?: string;
  ml?: string;
  pa?: string;
  or?: string;
  as?: string;
  ur?: string;
  ne?: string;
  // World languages
  es?: string;
  fr?: string;
  de?: string;
  pt?: string;
  ru?: string;
  ar?: string;
  zh?: string;
  ja?: string;
  ko?: string;
  it?: string;
  nl?: string;
  tr?: string;
  th?: string;
  vi?: string;
  id?: string;
  ms?: string;
}

// Languages that should show BILINGUAL format (English + Translation)
// These are Indian regional languages (except Hindi which shows direct translation)
const BILINGUAL_INDIAN_LANGUAGES: Language[] = ['mr', 'gu', 'ta', 'pa', 'bn', 'te', 'kn', 'ml', 'or', 'as', 'ur', 'ne'];

/**
 * Get text in bilingual format based on language
 * - For English: returns English text
 * - For Hindi: returns direct Hindi translation
 * - For Indian regional languages (Gujarati, Tamil, Punjabi, Marathi, etc.): returns "English (Translation)" format
 * - For world languages: returns "English (Translation)" format
 */
export const getBilingualText = (
  entry: BilingualEntry,
  language: Language
): string => {
  if (language === 'en') {
    return entry.en;
  }
  
  // For Hindi only, return direct translation
  if (language === 'hi') {
    return entry.hi || entry.en;
  }
  
  // For Indian regional languages (Gujarati, Tamil, Punjabi, Marathi, etc.), use bilingual format
  if (BILINGUAL_INDIAN_LANGUAGES.includes(language)) {
    const translation = entry[language as keyof BilingualEntry];
    if (translation && typeof translation === 'string') {
      return `${entry.en}\n(${translation})`;
    }
    // Fallback to Hindi bilingual if available
    if (entry.hi) {
      return `${entry.en}\n(${entry.hi})`;
    }
    return entry.en;
  }
  
  // For world languages, use bilingual format "English (Translation)"
  const translation = entry[language as keyof BilingualEntry];
  if (translation && typeof translation === 'string') {
    return `${entry.en} (${translation})`;
  }
  
  // Fallback to English if no translation
  return entry.en;
};

/**
 * Simple bilingual helper for inline usage
 * Returns proper format based on language
 * - Hindi: direct translation
 * - Indian regional languages: "English\n(Translation)" format with newline
 * - World languages: "English (Translation)" format
 */
export const bilingualFormat = (
  english: string,
  hindi: string,
  translations: Partial<Record<Language, string>> | undefined,
  language: Language
): string => {
  if (language === 'en') return english;
  
  // For Hindi only, return direct translation
  if (language === 'hi') return hindi || english;
  
  // For Indian regional languages, use bilingual format with newline
  if (BILINGUAL_INDIAN_LANGUAGES.includes(language)) {
    const translation = translations?.[language];
    if (translation) {
      return `${english}\n(${translation})`;
    }
    // Fallback to Hindi bilingual
    if (hindi) {
      return `${english}\n(${hindi})`;
    }
    return english;
  }
  
  // For world languages, use bilingual format inline
  const translation = translations?.[language];
  if (translation) {
    return `${english} (${translation})`;
  }
  
  return english;
};

