    mr: 'तुमच्याकडे कलात्मक प्रतिभा आणि ऐश्वर्याची आवड आहे. तुम्हाला कला, मनोरंजन किंवा मुत्सद्दीपणात यश मिळू शकते. तुमचे व्यक्तिमत्व स्वाभाविकपणे आकर्षक आहे.',
    bn: 'আপনার শৈল্পিক প্রতিভা এবং বিলাসিতার প্রতি ভালোবাসা আছে। আপনি শিল্প, বিনোদন বা কূটনীতিতে সাফল্য পেতে পারেন। আপনার ব্যক্তিত্ব স্বাভাবিকভাবেই আকর্ষণীয়।',
