    hi: 'आपका लग्न आपके शारीरिक रूप, स्वास्थ्य प्रवृत्तियों और दूसरों द्वारा पहली मुलाकात में आपको कैसे देखा जाता है, को आकार देता है।',
    mr: 'तुमचे लग्न तुमचा शारीरिक रूप, आरोग्याच्या प्रवृत्ती आणि पहिल्या भेटीत इतर तुम्हाला कसे पाहतात हे ठरवते.',
    bn: 'আপনার লগ্ন আপনার শারীরিক চেহারা, স্বাস্থ্য প্রবণতা এবং প্রথম সাক্ষাতে অন্যরা আপনাকে কীভাবে দেখে তা নির্ধারণ করে।',
