  'Zodiac compass explanation': {
    en: 'Imagine the zodiac as a compass. The 12 signs are grouped into 4 directions based on their elemental nature. Planets in the same direction "talk" to each other more easily!',
    hi: 'राशि चक्र को एक कंपास की तरह सोचें। 12 राशियों को उनकी तात्विक प्रकृति के आधार पर 4 दिशाओं में बांटा गया है। एक ही दिशा के ग्रह एक दूसरे से अधिक आसानी से "बात" करते हैं!',
    mr: 'राशी चक्राला कंपास म्हणून कल्पना करा. 12 राशी त्यांच्या तात्विक स्वभावानुसार 4 दिशांमध्ये विभागल्या आहेत. एकाच दिशेतील ग्रह एकमेकांशी सहज "बोलतात"!',
    bn: 'রাশিচক্রকে একটি কম্পাস হিসাবে কল্পনা করুন। ১২টি রাশি তাদের তাত্ত্বিক প্রকৃতির উপর ভিত্তি করে ৪টি দিকে বিভক্ত। একই দিকের গ্রহগুলি সহজেই "কথা বলে"!',
    te: 'రాశిచక్రాన్ని దిక్సూచిగా ఊహించుకోండి. 12 రాశులు వాటి తాత్విక స్వభావం ఆధారంగా 4 దిశలుగా విభజించబడ్డాయి. ఒకే దిశలోని గ్రహాలు సులభంగా "మాట్లాడతాయి"!',
    ta: 'ராசிச்சக்கரத்தை திசைகாட்டியாக கற்பனை செய்யுங்கள். 12 ராசிகள் அவற்றின் தாத்துவிக தன்மையின் அடிப்படையில் 4 திசைகளாக பிரிக்கப்பட்டுள்ளன. ஒரே திசையில் உள்ள கிரகங்கள் எளிதாக "பேசுகின்றன"!',
    gu: 'રાશિચક્રને હોકાયંત્ર તરીકે કલ્પના કરો. 12 રાશિઓ તેમના તાત્વિક સ્વભાવના આધારે 4 દિશાઓમાં વહેંચાયેલી છે. સમાન દિશાના ગ્રહો એકબીજા સાથે સહેલાઇથી "વાત કરે છે"!',
    kn: 'ರಾಶಿಚಕ್ರವನ್ನು ದಿಕ್ಸೂಚಿ ಎಂದು ಊಹಿಸಿ. 12 ರಾಶಿಗಳನ್ನು ಅವುಗಳ ತಾತ್ವಿಕ ಸ್ವಭಾವದ ಆಧಾರದ ಮೇಲೆ 4 ದಿಕ್ಕುಗಳಲ್ಲಿ ವಿಭಜಿಸಲಾಗಿದೆ. ಒಂದೇ ದಿಕ್ಕಿನ ಗ್ರಹಗಳು ಸುಲಭವಾಗಿ "ಮಾತನಾಡುತ್ತವೆ"!',
    ml: 'രാശിചക്രത്തെ ഒരു ദിശാസൂചി ആയി സങ്കൽപ്പിക്കുക. 12 രാശികൾ അവയുടെ തത്ത്വ സ്വഭാവത്തിന്റെ അടിസ്ഥാനത്തിൽ 4 ദിശകളായി വിഭജിച്ചിരിക്കുന്നു. ഒരേ ദിശയിലുള്ള ഗ്രഹങ്ങൾ എളുപ്പത്തിൽ "സംസാരിക്കുന്നു"!',
    pa: 'ਰਾਸ਼ੀ ਚੱਕਰ ਨੂੰ ਇੱਕ ਦਿਸ਼ਾ-ਸੂਚਕ ਵਜੋਂ ਕਲਪਨਾ ਕਰੋ। 12 ਰਾਸ਼ੀਆਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਤੱਤਵਿਕ ਸੁਭਾਅ ਦੇ ਆਧਾਰ \'ਤੇ 4 ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਵੰਡਿਆ ਗਿਆ ਹੈ। ਇੱਕੋ ਦਿਸ਼ਾ ਦੇ ਗ੍ਰਹਿ ਇੱਕ ਦੂਜੇ ਨਾਲ ਆਸਾਨੀ ਨਾਲ "ਗੱਲ ਕਰਦੇ ਹਨ"!',
    ur: 'برج کے چکر کو ایک قطب نما کے طور پر تصور کریں۔ 12 برجوں کو ان کی عنصری فطرت کی بنیاد پر 4 سمتوں میں تقسیم کیا گیا ہے۔ ایک ہی سمت کے سیارے آسانی سے "بات کرتے ہیں"!',
    ne: 'राशिचक्रलाई कम्पासको रूपमा कल्पना गर्नुहोस्। 12 राशिहरू तिनीहरूको तात्विक प्रकृतिको आधारमा 4 दिशाहरूमा विभाजित छन्। एउटै दिशाका ग्रहहरू सजिलै "कुरा गर्छन्"!',
  },
