  'Jupiter activates fire signs': {
    en: 'When Jupiter moves through Fire signs, it activates ALL your Fire sign planets together!',
    hi: 'जब बृहस्पति अग्नि राशियों से गुजरता है, तो यह आपके सभी अग्नि राशि ग्रहों को एक साथ सक्रिय करता है!',
    mr: 'जेव्हा गुरु अग्नी राशींमधून जातो, तो तुमच्या सर्व अग्नी राशी ग्रहांना एकत्र सक्रिय करतो!',
    bn: 'যখন বৃহস্পতি অগ্নি রাশিগুলির মধ্য দিয়ে যায়, এটি আপনার সমস্ত অগ্নি রাশি গ্রহগুলিকে একসাথে সক্রিয় করে!',
    te: 'బృహస్పతి అగ్ని రాశుల ద్వారా ప్రయాణించినప్పుడు, ఇది మీ అన్ని అగ్ని రాశి గ్రహాలను ఒకేసారి యాక్టివేట్ చేస్తుంది!',
    ta: 'குரு அக்னி ராசிகளில் பயணிக்கும்போது, இது உங்கள் அனைத்து அக்னி ராசி கிரகங்களையும் ஒன்றாக செயல்படுத்துகிறது!',
    gu: 'જ્યારે ગુરુ અગ્નિ રાશિઓમાંથી પસાર થાય છે, ત્યારે તે તમારા તમામ અગ્નિ રાશિ ગ્રહોને એકસાથે સક્રિય કરે છે!',
    kn: 'ಗುರು ಅಗ್ನಿ ರಾಶಿಗಳ ಮೂಲಕ ಚಲಿಸಿದಾಗ, ಅದು ನಿಮ್ಮ ಎಲ್ಲಾ ಅಗ್ನಿ ರಾಶಿ ಗ್ರಹಗಳನ್ನು ಒಟ್ಟಿಗೆ ಸಕ್ರಿಯಗೊಳಿಸುತ್ತದೆ!',
    ml: 'വ്യാഴം അഗ്നി രാശികളിലൂടെ നീങ്ങുമ്പോൾ, ഇത് നിങ്ങളുടെ എല്ലാ അഗ്നി രാശി ഗ്രഹങ്ങളെയും ഒരുമിച്ച് സജീവമാക്കുന്നു!',
    pa: 'ਜਦੋਂ ਬ੍ਰਿਹਸਪਤੀ ਅਗਨੀ ਰਾਸ਼ੀਆਂ ਵਿੱਚੋਂ ਲੰਘਦਾ ਹੈ, ਇਹ ਤੁਹਾਡੇ ਸਾਰੇ ਅਗਨੀ ਰਾਸ਼ੀ ਗ੍ਰਹਿਆਂ ਨੂੰ ਇਕੱਠੇ ਸਰਗਰਮ ਕਰਦਾ ਹੈ!',
    ur: 'جب مشتری آگ کی راشیوں سے گزرتا ہے، یہ آپ کے تمام آگ کی راشی سیاروں کو ایک ساتھ سرگرم کرتا ہے!',
    ne: 'जब बृहस्पति अग्नि राशिहरूबाट जान्छ, यसले तपाईंका सबै अग्नि राशि ग्रहहरूलाई एकसाथ सक्रिय गर्छ!',
  },
