    mr: 'सर्वाधिक ग्रह असलेली दिशा तुमचा प्रबळ तत्व आहे - जिथे तुमची ऊर्जा नैसर्गिकरित्या वाहते.',
    bn: 'সর্বাধিক গ্রহ সহ দিকটি আপনার প্রভাবশালী উপাদান - যেখানে আপনার শক্তি স্বাভাবিকভাবে প্রবাহিত হয়।',
    te: 'అత్యధిక గ్రహాలు ఉన్న దిశ మీ ప్రాబల్య మూలకం - మీ శక్తి సహజంగా ఎక్కడ ప్రవహిస్తుందో అక్కడ.',
    ta: 'அதிக கிரகங்கள் கொண்ட திசை உங்கள் ஆதிக்க மூலகம் - உங்கள் ஆற்றல் இயற்கையாக எங்கு பாய்கிறது என்பது.',
    gu: 'સૌથી વધુ ગ્રહો ધરાવતી દિશા તમારું પ્રબળ તત્વ છે - જ્યાં તમારી ઊર્જા કુદરતી રીતે વહે છે.',
    kn: 'ಹೆಚ್ಚು ಗ್ರಹಗಳಿರುವ ದಿಕ್ಕು ನಿಮ್ಮ ಪ್ರಬಲ ಅಂಶ - ನಿಮ್ಮ ಶಕ್ತಿ ಸ್ವಾಭಾವಿಕವಾಗಿ ಎಲ್ಲಿ ಹರಿಯುತ್ತದೆ.',
    ml: 'ഏറ്റവും കൂടുതൽ ഗ്രഹങ്ങളുള്ള ദിശ നിങ്ങളുടെ പ്രബലമായ മൂലകമാണ് - നിങ്ങളുടെ ഊർജ്ജം സ്വാഭാവികമായി ഒഴുകുന്നിടം.',
    pa: 'ਸਭ ਤੋਂ ਵੱਧ ਗ੍ਰਹਿਆਂ ਵਾਲੀ ਦਿਸ਼ਾ ਤੁਹਾਡਾ ਪ੍ਰਮੁੱਖ ਤੱਤ ਹੈ - ਜਿੱਥੇ ਤੁਹਾਡੀ ਊਰਜਾ ਕੁਦਰਤੀ ਤੌਰ \'ਤੇ ਵਹਿੰਦੀ ਹੈ।',
