  'Birth chart distribution': {
    en: 'Based on your birth chart, here\'s how your planets are distributed across the 4 elemental directions. Each grouping reveals your natural strengths and the life areas where energy flows most easily.',
    hi: 'आपकी जन्म कुंडली के आधार पर, यहां बताया गया है कि आपके ग्रह 4 तात्विक दिशाओं में कैसे वितरित हैं। प्रत्येक समूह आपकी प्राकृतिक शक्तियों और जीवन के उन क्षेत्रों को प्रकट करता है जहां ऊर्जा सबसे आसानी से प्रवाहित होती है।',
    mr: 'तुमच्या जन्म कुंडलीच्या आधारे, तुमचे ग्रह 4 तात्विक दिशांमध्ये कसे वितरित आहेत ते येथे आहे. प्रत्येक गट तुमची नैसर्गिक शक्ती आणि ऊर्जा सर्वात सहजपणे वाहणारे जीवनाचे क्षेत्र प्रकट करतो.',
    bn: 'আপনার জন্ম কুণ্ডলীর উপর ভিত্তি করে, আপনার গ্রহগুলি 4টি তাত্ত্বিক দিকে কীভাবে বিতরণ করা হয়েছে তা এখানে দেওয়া হয়েছে। প্রতিটি গোষ্ঠী আপনার প্রাকৃতিক শক্তি এবং জীবনের সেই ক্ষেত্রগুলি প্রকাশ করে যেখানে শক্তি সবচেয়ে সহজে প্রবাহিত হয়।',
    te: 'మీ జన్మ కుండలి ఆధారంగా, మీ గ్రహాలు 4 తాత్విక దిశల్లో ఎలా పంపిణీ చేయబడ్డాయో ఇక్కడ ఉంది. ప్రతి సమూహం మీ సహజ బలాలను మరియు శక్తి అత్యంత సులభంగా ప్రవహించే జీవిత ప్రాంతాలను వెల్లడిస్తుంది.',
    ta: 'உங்கள் ஜாதகத்தின் அடிப்படையில், உங்கள் கிரகங்கள் 4 தாத்துவிக திசைகளில் எவ்வாறு விநியோகிக்கப்படுகின்றன என்பது இங்கே. ஒவ்வொரு குழுவும் உங்கள் இயற்கையான பலங்களையும் ஆற்றல் எளிதாக பாயும் வாழ்க்கை பகுதிகளையும் வெளிப்படுத்துகிறது.',
    gu: 'તમારી જન્મ કુંડળીના આધારે, અહીં તમારા ગ્રહો 4 તાત્વિક દિશાઓમાં કેવી રીતે વિતરિત છે તે છે. દરેક જૂથ તમારી કુદરતી શક્તિઓ અને જીવનના તે ક્ષેત્રો પ્રગટ કરે છે જ્યાં ઊર્જા સૌથી સરળતાથી વહે છે.',
    kn: 'ನಿಮ್ಮ ಜನ್ಮ ಕುಂಡಲಿಯ ಆಧಾರದ ಮೇಲೆ, ನಿಮ್ಮ ಗ್ರಹಗಳು 4 ತಾತ್ವಿಕ ದಿಕ್ಕುಗಳಲ್ಲಿ ಹೇಗೆ ವಿತರಣೆಯಾಗಿವೆ ಎಂಬುದು ಇಲ್ಲಿದೆ. ಪ್ರತಿ ಗುಂಪು ನಿಮ್ಮ ನೈಸರ್ಗಿಕ ಶಕ್ತಿಗಳು ಮತ್ತು ಶಕ್ತಿ ಅತ್ಯಂತ ಸುಲಭವಾಗಿ ಹರಿಯುವ ಜೀವನ ಕ್ಷೇತ್ರಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸುತ್ತದೆ.',
    ml: 'നിങ്ങളുടെ ജാതകത്തെ അടിസ്ഥാനമാക്കി, നിങ്ങളുടെ ഗ്രഹങ്ങൾ 4 തത്ത്വ ദിശകളിൽ എങ്ങനെ വിതരണം ചെയ്യപ്പെട്ടിരിക്കുന്നു എന്നത് ഇവിടെയുണ്ട്. ഓരോ ഗ്രൂപ്പും നിങ്ങളുടെ സ്വാഭാവിക ശക്തികളും ഊർജ്ജം ഏറ്റവും എളുപ്പത്തിൽ ഒഴുകുന്ന ജീവിത മേഖലകളും വെളിപ്പെടുത്തുന്നു.',
    pa: 'ਤੁਹਾਡੀ ਜਨਮ ਕੁੰਡਲੀ ਦੇ ਆਧਾਰ \'ਤੇ, ਇੱਥੇ ਦੱਸਿਆ ਗਿਆ ਹੈ ਕਿ ਤੁਹਾਡੇ ਗ੍ਰਹਿ 4 ਤੱਤਵਿਕ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਕਿਵੇਂ ਵੰਡੇ ਹੋਏ ਹਨ। ਹਰੇਕ ਸਮੂਹ ਤੁਹਾਡੀਆਂ ਕੁਦਰਤੀ ਸ਼ਕਤੀਆਂ ਅਤੇ ਜੀਵਨ ਦੇ ਉਨ੍ਹਾਂ ਖੇਤਰਾਂ ਨੂੰ ਪ੍ਰਗਟ ਕਰਦਾ ਹੈ ਜਿੱਥੇ ਊਰਜਾ ਸਭ ਤੋਂ ਆਸਾਨੀ ਨਾਲ ਵਹਿੰਦੀ ਹੈ।',
    ur: 'آپ کی جنم کنڈلی کی بنیاد پر، یہاں بتایا گیا ہے کہ آپ کے سیارے 4 عنصری سمتوں میں کیسے تقسیم ہیں۔ ہر گروہ آپ کی فطری طاقتوں اور زندگی کے ان شعبوں کو ظاہر کرتا ہے جہاں توانائی سب سے آسانی سے بہتی ہے۔',
    ne: 'तपाईंको जन्म कुण्डलीको आधारमा, तपाईंका ग्रहहरू 4 तात्विक दिशाहरूमा कसरी वितरित छन् भन्ने यहाँ छ। प्रत्येक समूहले तपाईंको प्राकृतिक शक्तिहरू र जीवनका ती क्षेत्रहरू प्रकट गर्दछ जहाँ ऊर्जा सबैभन्दा सजिलो रूपमा बग्छ।',
  },
