  'No planets empty elements': {
    en: 'No planets in these elements. Consciously developing these qualities through activities and relationships can bring balance to your life.',
    hi: 'इन तत्वों में कोई ग्रह नहीं है। गतिविधियों और संबंधों के माध्यम से इन गुणों को सचेत रूप से विकसित करने से आपके जीवन में संतुलन आ सकता है।',
    mr: 'या तत्वांमध्ये कोणतेही ग्रह नाहीत. क्रियाकलाप आणि नातेसंबंधांद्वारे या गुणांचा जाणीवपूर्वक विकास केल्याने तुमच्या जीवनात संतुलन येऊ शकते.',
    bn: 'এই উপাদানগুলিতে কোনো গ্রহ নেই। কার্যকলাপ এবং সম্পর্কের মাধ্যমে এই গুণগুলি সচেতনভাবে বিকাশ করলে আপনার জীবনে ভারসাম্য আসতে পারে।',
    te: 'ఈ మూలకాలలో గ్రహాలు లేవు. కార్యకలాపాలు మరియు సంబంధాల ద్వారా ఈ లక్షణాలను చైతన్యంతో అభివృద్ధి చేయడం వల్ల మీ జీవితంలో సమతుల్యత రావచ్చు.',
    ta: 'இந்த மூலகங்களில் கிரகங்கள் இல்லை. செயல்பாடுகள் மற்றும் உறவுகள் மூலம் இந்த குணங்களை உணர்வுபூர்வமாக வளர்ப்பது உங்கள் வாழ்க்கையில் சமநிலையை கொண்டுவரலாம்.',
    gu: 'આ તત્વોમાં કોઈ ગ્રહો નથી. પ્રવૃત્તિઓ અને સંબંધો દ્વારા આ ગુણોને સભાનપણે વિકસાવવાથી તમારા જીવનમાં સંતુલન આવી શકે છે.',
    kn: 'ಈ ಅಂಶಗಳಲ್ಲಿ ಯಾವುದೇ ಗ್ರಹಗಳಿಲ್ಲ. ಚಟುವಟಿಕೆಗಳು ಮತ್ತು ಸಂಬಂಧಗಳ ಮೂಲಕ ಈ ಗುಣಗಳನ್ನು ಜಾಗೃತವಾಗಿ ಅಭಿವೃದ್ಧಿಪಡಿಸುವುದು ನಿಮ್ಮ ಜೀವನದಲ್ಲಿ ಸಮತೋಲನ ತರಬಹುದು.',
    ml: 'ഈ മൂലകങ്ങളിൽ ഗ്രഹങ്ങളില്ല. പ്രവർത്തനങ്ങളിലൂടെയും ബന്ധങ്ങളിലൂടെയും ഈ ഗുണങ്ങൾ ബോധപൂർവ്വം വികസിപ്പിക്കുന്നത് നിങ്ങളുടെ ജീവിതത്തിൽ സന്തുലനം കൊണ്ടുവരും.',
    pa: 'ਇਹਨਾਂ ਤੱਤਾਂ ਵਿੱਚ ਕੋਈ ਗ੍ਰਹਿ ਨਹੀਂ ਹੈ। ਗਤੀਵਿਧੀਆਂ ਅਤੇ ਰਿਸ਼ਤਿਆਂ ਰਾਹੀਂ ਇਹਨਾਂ ਗੁਣਾਂ ਨੂੰ ਸੁਚੇਤ ਰੂਪ ਵਿੱਚ ਵਿਕਸਿਤ ਕਰਨਾ ਤੁਹਾਡੀ ਜ਼ਿੰਦਗੀ ਵਿੱਚ ਸੰਤੁਲਨ ਲਿਆ ਸਕਦਾ ਹੈ।',
    ur: 'ان عناصر میں کوئی سیارے نہیں ہیں۔ سرگرمیوں اور رشتوں کے ذریعے ان خوبیوں کو شعوری طور پر ترقی دینے سے آپ کی زندگی میں توازن آ سکتا ہے۔',
    ne: 'यी तत्वहरूमा कुनै ग्रह छैनन्। क्रियाकलापहरू र सम्बन्धहरू मार्फत यी गुणहरूलाई सचेत रूपमा विकास गर्दा तपाईंको जीवनमा सन्तुलन ल्याउन सक्छ।',
  },
