  'Connections description': {
    en: 'These are the actual planet-to-planet connections found in YOUR chart. Each connection shows how strongly these planets influence each other and what it means for your life.',
    hi: 'ये आपकी कुंडली में पाए जाने वाले वास्तविक ग्रह-से-ग्रह संबंध हैं। प्रत्येक संबंध दिखाता है कि ये ग्रह एक दूसरे को कितनी मजबूती से प्रभावित करते हैं और आपके जीवन के लिए इसका क्या अर्थ है।',
    mr: 'हे तुमच्या कुंडलीत आढळलेले वास्तविक ग्रह-ते-ग्रह संबंध आहेत. प्रत्येक संबंध दाखवतो की हे ग्रह एकमेकांवर किती मजबूतपणे प्रभाव टाकतात आणि तुमच्या जीवनासाठी याचा काय अर्थ आहे.',
    bn: 'এগুলি আপনার কুণ্ডলীতে পাওয়া প্রকৃত গ্রহ-থেকে-গ্রহ সংযোগ। প্রতিটি সংযোগ দেখায় এই গ্রহগুলি একে অপরকে কতটা শক্তিশালীভাবে প্রভাবিত করে এবং আপনার জীবনের জন্য এর অর্থ কী।',
    te: 'ఇవి మీ కుండలిలో కనుగొన్న వాస్తవ గ్రహం-నుండి-గ్రహం కనెక్షన్లు. ప్రతి కనెక్షన్ ఈ గ్రహాలు ఒకదానినొకటి ఎంత బలంగా ప్రభావితం చేస్తాయో మరియు మీ జీవితానికి దీని అర్థం ఏమిటో చూపిస్తుంది.',
    ta: 'இவை உங்கள் ஜாதகத்தில் காணப்படும் உண்மையான கிரகம்-க்கு-கிரக இணைப்புகள். ஒவ்வொரு இணைப்பும் இந்த கிரகங்கள் ஒருவரை ஒருவர் எவ்வளவு வலுவாக பாதிக்கின்றன என்பதையும் உங்கள் வாழ்க்கைக்கு இதன் பொருள் என்ன என்பதையும் காட்டுகிறது.',
    gu: 'આ તમારી કુંડળીમાં જોવા મળેલ વાસ્તવિક ગ્રહ-થી-ગ્રહ જોડાણો છે. દરેક જોડાણ બતાવે છે કે આ ગ્રહો એકબીજાને કેટલી મજબૂતીથી પ્રભાવિત કરે છે અને તમારા જીવન માટે આનો શું અર્થ છે.',
    kn: 'ಇವು ನಿಮ್ಮ ಕುಂಡಲಿಯಲ್ಲಿ ಕಂಡುಬಂದ ನಿಜವಾದ ಗ್ರಹ-ಇಂದ-ಗ್ರಹ ಸಂಪರ್ಕಗಳು. ಪ್ರತಿ ಸಂಪರ್ಕವು ಈ ಗ್ರಹಗಳು ಪರಸ್ಪರವನ್ನು ಎಷ್ಟು ಬಲವಾಗಿ ಪ್ರಭಾವಿಸುತ್ತವೆ ಮತ್ತು ನಿಮ್ಮ ಜೀವನಕ್ಕೆ ಇದರ ಅರ್ಥವೇನು ಎಂಬುದನ್ನು ತೋರಿಸುತ್ತದೆ.',
    ml: 'ഇവ നിങ്ങളുടെ ജാതകത്തിൽ കണ്ടെത്തിയ യഥാർത്ഥ ഗ്രഹ-മുതൽ-ഗ്രഹ കണക്ഷനുകളാണ്. ഓരോ കണക്ഷനും ഈ ഗ്രഹങ്ങൾ പരസ്പരം എത്രമാത്രം ശക്തമായി സ്വാധീനിക്കുന്നുവെന്നും നിങ്ങളുടെ ജീവിതത്തിന് ഇതിന്റെ അർത്ഥമെന്താണെന്നും കാണിക്കുന്നു.',
    pa: 'ਇਹ ਤੁਹਾਡੀ ਕੁੰਡਲੀ ਵਿੱਚ ਮਿਲੇ ਅਸਲ ਗ੍ਰਹਿ-ਤੋਂ-ਗ੍ਰਹਿ ਕੁਨੈਕਸ਼ਨ ਹਨ। ਹਰੇਕ ਕੁਨੈਕਸ਼ਨ ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਇਹ ਗ੍ਰਹਿ ਇੱਕ ਦੂਜੇ ਨੂੰ ਕਿੰਨੀ ਮਜ਼ਬੂਤੀ ਨਾਲ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ ਅਤੇ ਤੁਹਾਡੀ ਜ਼ਿੰਦਗੀ ਲਈ ਇਸਦਾ ਕੀ ਮਤਲਬ ਹੈ।',
    ur: 'یہ آپ کی کنڈلی میں پائے جانے والے اصل سیارے سے سیارے کے رابطے ہیں۔ ہر رابطہ دکھاتا ہے کہ یہ سیارے ایک دوسرے کو کتنی مضبوطی سے متاثر کرتے ہیں اور آپ کی زندگی کے لیے اس کا کیا مطلب ہے۔',
    ne: 'यी तपाईंको कुण्डलीमा पाइएका वास्तविक ग्रह-देखि-ग्रह जडानहरू हुन्। प्रत्येक जडानले यी ग्रहहरू एकअर्कालाई कत्तिको बलियोसँग प्रभाव पार्छन् र तपाईंको जीवनको लागि यसको अर्थ के हो भनेर देखाउँछ।',
  },
