    mr: 'या घरांतील ग्रह आरोग्य कमकुवतपणा दर्शवतात. 6वा तीव्र रोग, 8वा दीर्घकालीन स्थिती, 12वा रुग्णालयात दाखल.',
    bn: 'এই ঘরগুলিতে গ্রহ স্বাস্থ্য দুর্বলতা নির্দেশ করে। ৬ষ্ঠ তীব্র রোগ, ৮ম দীর্ঘস্থায়ী অবস্থা, ১২তম হাসপাতালে ভর্তি।',
