    ta: 'இந்த வீடுகளில் உள்ள கிரகங்கள் ஆரோக்கிய பலவீனங்களைக் குறிக்கின்றன. 6வது கடுமையான நோய்கள், 8வது நாள்பட்ட நிலைகள், 12வது மருத்துவமனையில் அனுமதி.',
    gu: 'આ ઘરોમાં ગ્રહો આરોગ્ય નબળાઈઓ દર્શાવે છે. 6ઠ્ઠું તીવ્ર રોગો, 8મું ક્રોનિક સ્થિતિઓ, 12મું હોસ્પિટલમાં દાખલ.',
