  'Medical disclaimer text': {
    en: 'This astrological health analysis is for educational and awareness purposes only. It is NOT a substitute for professional medical advice, diagnosis, or treatment. Always consult qualified healthcare professionals for any health concerns. Gemstones and remedies should be adopted only after consulting a qualified astrologer.',
    hi: 'यह ज्योतिषीय स्वास्थ्य विश्लेषण केवल शैक्षिक और जागरूकता उद्देश्यों के लिए है। यह पेशेवर चिकित्सा सलाह, निदान या उपचार का विकल्प नहीं है। किसी भी स्वास्थ्य चिंता के लिए हमेशा योग्य स्वास्थ्य पेशेवरों से परामर्श करें। रत्न और उपाय केवल योग्य ज्योतिषी से परामर्श के बाद अपनाएं।',
    mr: 'हे ज्योतिषशास्त्रीय आरोग्य विश्लेषण केवळ शैक्षणिक आणि जागरूकता उद्देशांसाठी आहे. हे व्यावसायिक वैद्यकीय सल्ला, निदान किंवा उपचारांचा पर्याय नाही. कोणत्याही आरोग्य चिंतेसाठी नेहमी पात्र आरोग्य व्यावसायिकांचा सल्ला घ्या.',
    bn: 'এই জ্যোতিষশাস্ত্রীয় স্বাস্থ্য বিশ্লেষণ শুধুমাত্র শিক্ষামূলক এবং সচেতনতার উদ্দেশ্যে। এটি পেশাদার চিকিৎসা পরামর্শ, রোগ নির্ণয় বা চিকিৎসার বিকল্প নয়। যেকোনো স্বাস্থ্য উদ্বেগের জন্য সর্বদা যোগ্য স্বাস্থ্যসেবা পেশাদারদের সাথে পরামর্শ করুন।',
    te: 'ఈ జ్యోతిష ఆరోగ్య విశ్లేషణ విద్యా మరియు అవగాహన ప్రయోజనాల కోసం మాత్రమే. ఇది వృత్తిపరమైన వైద్య సలహా, రోగ నిర్ధారణ లేదా చికిత్సకు ప్రత్యామ్నాయం కాదు. ఏదైనా ఆరోగ్య సమస్యల కోసం ఎల్లప్పుడూ అర్హత గల ఆరోగ్య నిపుణులను సంప్రదించండి.',
    ta: 'இந்த ஜோதிட சுகாதார பகுப்பாய்வு கல்வி மற்றும் விழிப்புணர்வு நோக்கங்களுக்கு மட்டுமே. இது தொழில்முறை மருத்துவ ஆலோசனை, நோயறிதல் அல்லது சிகிச்சைக்கு மாற்றாக இல்லை. எந்தவொரு சுகாதார கவலைகளுக்கும் எப்போதும் தகுதியான சுகாதார நிபுணர்களை அணுகுங்கள்.',
    gu: 'આ જ્યોતિષશાસ્ત્રીય આરોગ્ય વિશ્લેષણ માત્ર શૈક્ષણિક અને જાગૃતિના હેતુઓ માટે છે. તે વ્યાવસાયિક તબીબી સલાહ, નિદાન અથવા સારવારનો વિકલ્પ નથી. કોઈપણ આરોગ્ય ચિંતાઓ માટે હંમેશા લાયક આરોગ્ય વ્યાવસાયિકોની સલાહ લો.',
    pa: 'ਇਹ ਜੋਤਿਸ਼ੀ ਸਿਹਤ ਵਿਸ਼ਲੇਸ਼ਣ ਸਿਰਫ਼ ਸਿੱਖਿਆ ਅਤੇ ਜਾਗਰੂਕਤਾ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਹੈ। ਇਹ ਪੇਸ਼ੇਵਰ ਡਾਕਟਰੀ ਸਲਾਹ, ਤਸ਼ਖ਼ੀਸ ਜਾਂ ਇਲਾਜ ਦਾ ਬਦਲ ਨਹੀਂ ਹੈ। ਕਿਸੇ ਵੀ ਸਿਹਤ ਚਿੰਤਾਵਾਂ ਲਈ ਹਮੇਸ਼ਾ ਯੋਗ ਸਿਹਤ ਪੇਸ਼ੇਵਰਾਂ ਨਾਲ ਸਲਾਹ ਕਰੋ।',
  },

