    bn: 'কেতুর সাথে একই ভাবে আছে। এই গ্রহগুলির শক্তি পূর্বজন্মের প্যাটার্ন দ্বারা প্রভাবিত এবং বিচ্ছিন্ন বা আধ্যাত্মিক অনুভব হতে পারে।',
