    ta: 'கேதுவுடன் ஒரே பாவத்தில் உள்ளன. இந்த கிரகங்களின் ஆற்றல்கள் கடந்த கால ஜன்ம முறைகளால் பாதிக்கப்படுகின்றன மற்றும் பற்றற்ற அல்லது ஆன்மீக உணர்வு கொள்ளலாம்.',
