    pa: 'ਕੇਤੂ ਨਾਲ ਇੱਕੋ ਭਾਵ ਵਿੱਚ ਹਨ। ਇਨ੍ਹਾਂ ਗ੍ਰਹਿਆਂ ਦੀ ਊਰਜਾ ਪਿਛਲੇ ਜਨਮ ਦੇ ਪੈਟਰਨਾਂ ਤੋਂ ਪ੍ਰਭਾਵਿਤ ਹੈ ਅਤੇ ਵੈਰਾਗੀ ਜਾਂ ਅਧਿਆਤਮਿਕ ਮਹਿਸੂਸ ਹੋ ਸਕਦੀ ਹੈ।',
