  'Foreign travel astrology explanation': {
    en: 'Certain planetary positions indicate foreign travel or settlement. The 3rd house shows short trips, 9th house shows long journeys, and 12th house shows foreign residence. Rahu is the main planet for foreign connections.',
    hi: 'कुछ ग्रह स्थितियां विदेश यात्रा या बसावट का संकेत देती हैं। 3वां भाव छोटी यात्राएं, 9वां भाव लंबी यात्राएं और 12वां भाव विदेश निवास दिखाता है। राहु विदेशी संबंधों के लिए मुख्य ग्रह है।',
    mr: 'काही ग्रह स्थिती विदेश यात्रा किंवा स्थायिक होण्याचे संकेत देतात. 3रा भाव छोट्या यात्रा, 9वा भाव लांब यात्रा आणि 12वा भाव विदेश निवास दर्शवतो. राहू विदेशी संबंधांसाठी मुख्य ग्रह आहे.',
    bn: 'নির্দিষ্ট গ্রহ অবস্থান বিদেশ ভ্রমণ বা বসতির ইঙ্গিত দেয়। ৩য় ভাব ছোট ভ্রমণ, ৯ম ভাব দীর্ঘ ভ্রমণ এবং ১২তম ভাব বিদেশ বসবাস দেখায়। রাহু বিদেশি সংযোগের জন্য প্রধান গ্রহ।',
    te: 'కొన్ని గ్రహ స్థానాలు విదేశ ప్రయాణం లేదా స్థిరపడటాన్ని సూచిస్తాయి. 3వ భావం చిన్న ప్రయాణాలు, 9వ భావం దూర ప్రయాణాలు మరియు 12వ భావం విదేశ నివాసాన్ని చూపిస్తుంది. రాహు విదేశీ సంబంధాలకు ప్రధాన గ్రహం.',
    ta: 'குறிப்பிட்ட கிரக நிலைகள் வெளிநாட்டு பயணம் அல்லது குடியேற்றத்தைக் குறிக்கின்றன. 3வது பாவம் குறுகிய பயணங்கள், 9வது பாவம் நீண்ட பயணங்கள் மற்றும் 12வது பாவம் வெளிநாட்டு வசிப்பைக் காட்டுகிறது. ராகு வெளிநாட்டு தொடர்புகளுக்கான முக்கிய கிரகம்.',
    gu: 'ચોક્કસ ગ્રહ સ્થિતિઓ વિદેશ યાત્રા અથવા વસવાટ સૂચવે છે. 3જો ભાવ ટૂંકી યાત્રાઓ, 9મો ભાવ લાંબી યાત્રાઓ અને 12મો ભાવ વિદેશ નિવાસ દર્શાવે છે. રાહુ વિદેશી સંબંધો માટે મુખ્ય ગ્રહ છે.',
    pa: 'ਕੁਝ ਗ੍ਰਹਿ ਸਥਿਤੀਆਂ ਵਿਦੇਸ਼ ਯਾਤਰਾ ਜਾਂ ਬਸੇਰੇ ਦਾ ਸੰਕੇਤ ਦਿੰਦੀਆਂ ਹਨ। 3ਵਾਂ ਭਾਵ ਛੋਟੀਆਂ ਯਾਤਰਾਵਾਂ, 9ਵਾਂ ਭਾਵ ਲੰਬੀਆਂ ਯਾਤਰਾਵਾਂ ਅਤੇ 12ਵਾਂ ਭਾਵ ਵਿਦੇਸ਼ ਨਿਵਾਸ ਦਿਖਾਉਂਦਾ ਹੈ। ਰਾਹੂ ਵਿਦੇਸ਼ੀ ਸੰਬੰਧਾਂ ਲਈ ਮੁੱਖ ਗ੍ਰਹਿ ਹੈ।',
  },
