    bn: 'কোনো নির্দিষ্ট ধন যোগ পাওয়া যায়নি। অনুকূল দশা সময়কালে ধারাবাহিক প্রচেষ্টার মাধ্যমে আর্থিক বৃদ্ধি হতে পারে।',
