    ta: 'குறிப்பிட்ட தன யோகங்கள் எதுவும் கண்டறியப்படவில்லை. சாதகமான தசா காலங்களில் தொடர்ச்சியான முயற்சிகளின் மூலம் நிதி வளர்ச்சி வரலாம்.',
