  'Remedies Description': {
    en: 'Remedies prioritized based on challenging yogs in your chart. Following these remedies with faith and regularity can help mitigate negative planetary influences and enhance positive ones.',
    hi: 'आपकी कुंडली में चुनौतीपूर्ण योगों के आधार पर प्राथमिकता वाले उपाय। इन उपायों को श्रद्धा और नियमितता से करने पर नकारात्मक ग्रहीय प्रभावों को कम करने और सकारात्मक प्रभावों को बढ़ाने में सहायता मिलती है।',
    mr: 'तुमच्या कुंडलीतील आव्हानात्मक योगांच्या आधारे प्राधान्य दिलेले उपाय. या उपायांचे श्रद्धा आणि नियमिततेने पालन केल्यास नकारात्मक ग्रहीय प्रभाव कमी करण्यात आणि सकारात्मक प्रभाव वाढवण्यात मदत होते.',
    bn: 'আপনার চার্টে চ্যালেঞ্জিং যোগের উপর ভিত্তি করে অগ্রাধিকার প্রতিকার। বিশ্বাস এবং নিয়মিততার সাথে এই প্রতিকারগুলি অনুসরণ করা নেতিবাচক গ্রহীয় প্রভাব কমাতে এবং ইতিবাচক প্রভাব বাড়াতে সাহায্য করতে পারে।',
    te: 'మీ చార్ట్‌లోని సవాలు యోగాల ఆధారంగా ప్రాధాన్యత ఉపాయాలు. విశ్వాసం మరియు క్రమబద్ధతతో ఈ ఉపాయాలను అనుసరించడం ప్రతికూల గ్రహ ప్రభావాలను తగ్గించడానికి మరియు సానుకూల వాటిని పెంచడానికి సహాయపడుతుంది.',
    ta: 'உங்கள் ஜாதகத்தில் சவாலான யோகங்களின் அடிப்படையில் முன்னுரிமை பரிகாரங்கள். நம்பிக்கை மற்றும் தொடர்ச்சியாக இந்த பரிகாரங்களை பின்பற்றுவது எதிர்மறை கிரக தாக்கங்களைக் குறைக்கவும் நேர்மறையானவற்றை மேம்படுத்தவும் உதவும்.',
    gu: 'તમારી કુંડળીમાં પડકારજનક યોગના આધારે પ્રાથમિકતા ઉપાયો. શ્રદ્ધા અને નિયમિતતા સાથે આ ઉપાયોનું પાલન નકારાત્મક ગ્રહ પ્રભાવોને ઘટાડવામાં અને હકારાત્મક પ્રભાવોને વધારવામાં મદદ કરી શકે છે.',
    pa: 'ਤੁਹਾਡੀ ਕੁੰਡਲੀ ਵਿੱਚ ਚੁਣੌਤੀਪੂਰਨ ਯੋਗਾਂ ਦੇ ਆਧਾਰ \'ਤੇ ਤਰਜੀਹੀ ਉਪਾਅ। ਵਿਸ਼ਵਾਸ ਅਤੇ ਨਿਯਮਿਤਤਾ ਨਾਲ ਇਹਨਾਂ ਉਪਾਵਾਂ ਦੀ ਪਾਲਣਾ ਕਰਨਾ ਨਕਾਰਾਤਮਕ ਗ੍ਰਹਿ ਪ੍ਰਭਾਵਾਂ ਨੂੰ ਘਟਾਉਣ ਅਤੇ ਸਕਾਰਾਤਮਕ ਪ੍ਰਭਾਵਾਂ ਨੂੰ ਵਧਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ।',
  },
