  'BNN Combination Principles Description': {
    en: 'In Bhrigu Nandi Nadi, planetary combinations reveal life patterns. When two or more planets conjoin in a house, their combined significations manifest. The stronger planet (by degrees) dominates, and effects vary based on house placement.',
    hi: 'भृगु नंदी नाड़ी में, ग्रह संयोजन जीवन पैटर्न प्रकट करते हैं। जब दो या अधिक ग्रह एक भाव में संयोजित होते हैं, उनके संयुक्त कारकत्व प्रकट होते हैं। अधिक अंश वाला ग्रह प्रभावी होता है।',
    mr: 'भृगु नंदी नाडीमध्ये, ग्रह संयोजन जीवन पद्धती प्रकट करतात. जेव्हा दोन किंवा अधिक ग्रह एका भावात एकत्र येतात, तेव्हा त्यांचे संयुक्त कारकत्व प्रकट होते. अधिक अंश असलेला ग्रह प्रभावी असतो.',
    bn: 'ভৃগু নন্দী নাড়িতে, গ্রহ সংযোগ জীবনের ধরণ প্রকাশ করে। যখন দুই বা ততোধিক গ্রহ একটি ভাবে সংযুক্ত হয়, তাদের সম্মিলিত কারকত্ব প্রকাশ পায়। বেশি অংশের গ্রহ প্রভাবশালী হয়।',
    te: 'భృగు నంది నాడిలో, గ్రహ సంయోజనాలు జీవిత నమూనాలను వెల్లడిస్తాయి. రెండు లేదా అంతకంటే ఎక్కువ గ్రహాలు ఒక భావంలో కలిసినప్పుడు, వారి సంయుక్త కారకత్వం వ్యక్తమవుతుంది.',
    ta: 'பிருகு நந்தி நாடியில், கிரக சேர்க்கைகள் வாழ்க்கை முறைகளை வெளிப்படுத்துகின்றன. இரண்டு அல்லது அதற்கு மேற்பட்ட கிரகங்கள் ஒரு பாவத்தில் இணையும்போது, அவற்றின் கூட்டு காரகத்துவம் வெளிப்படுகிறது.',
    gu: 'ભૃગુ નંદી નાડીમાં, ગ્રહ સંયોજનો જીવન પેટર્ન પ્રગટ કરે છે. જ્યારે બે અથવા વધુ ગ્રહો એક ભાવમાં જોડાય છે, ત્યારે તેમના સંયુક્ત કારકત્વ પ્રગટ થાય છે.',
    pa: 'ਭ੃ਗੁ ਨੰਦੀ ਨਾੜੀ ਵਿੱਚ, ਗ੍ਰਹਿ ਸੁਮੇਲ ਜੀਵਨ ਪੈਟਰਨ ਪ੍ਰਗਟ ਕਰਦੇ ਹਨ। ਜਦੋਂ ਦੋ ਜਾਂ ਵੱਧ ਗ੍ਰਹਿ ਇੱਕ ਭਾਵ ਵਿੱਚ ਜੁੜਦੇ ਹਨ, ਉਹਨਾਂ ਦੇ ਸੰਯੁਕਤ ਕਾਰਕਤਵ ਪ੍ਰਗਟ ਹੁੰਦੇ ਹਨ।',
  },
