  'Planet Significators Description': {
    en: 'Each planet represents specific significations in BNN. Understanding these helps interpret combinations accurately.',
    hi: 'प्रत्येक ग्रह BNN में विशिष्ट कारकत्व दर्शाता है। इन्हें समझने से संयोजनों की सही व्याख्या होती है।',
    mr: 'प्रत्येक ग्रह BNN मध्ये विशिष्ट कारकत्व दर्शवतो. हे समजून घेतल्यास संयोजनांचा अचूक अर्थ लावता येतो.',
    bn: 'প্রতিটি গ্রহ BNN-এ নির্দিষ্ট কারকত্ব প্রতিনিধিত্ব করে। এগুলো বোঝা সংযোগের সঠিক ব্যাখ্যা করতে সাহায্য করে।',
    te: 'ప్రతి గ్రహం BNN లో నిర్దిష్ట కారకత్వాన్ని సూచిస్తుంది. వీటిని అర్థం చేసుకోవడం సంయోజనాలను సరిగ్గా అర్థం చేసుకోవడంలో సహాయపడుతుంది.',
    ta: 'ஒவ்வொரு கிரகமும் BNN இல் குறிப்பிட்ட காரகத்துவத்தை குறிக்கிறது. இவற்றை புரிந்துகொள்வது சேர்க்கைகளை துல்லியமாக விளக்க உதவுகிறது.',
    gu: 'દરેક ગ્રહ BNN માં વિશિષ્ટ કારકત્વ દર્શાવે છે. આને સમજવું સંયોજનોનું સચોટ અર્થઘટન કરવામાં મદદ કરે છે.',
    pa: 'ਹਰ ਗ੍ਰਹਿ BNN ਵਿੱਚ ਵਿਸ਼ੇਸ਼ ਕਾਰਕਤਵ ਦਰਸਾਉਂਦਾ ਹੈ। ਇਹਨਾਂ ਨੂੰ ਸਮਝਣਾ ਸੁਮੇਲਾਂ ਦੀ ਸਹੀ ਵਿਆਖਿਆ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।',
  },
