  'BNN System Description': {
    en: 'The Bhrighu Nandi Nadi system evaluates planetary relationships based on their house positions. The strength of connection depends on the angular relationship between planets - same house (100%), trine (75%), 2/12 (60%), opposition (50%), and 3/11 (15-20%). Understanding these relationships helps predict how planetary energies combine to influence different life areas.',
    hi: 'भृगु नंदी नाड़ी प्रणाली ग्रहों के भाव स्थानों के आधार पर उनके संबंधों का मूल्यांकन करती है। संबंध की शक्ति ग्रहों के बीच कोणीय संबंध पर निर्भर करती है।',
    mr: 'भृगु नंदी नाडी प्रणाली ग्रहांच्या भाव स्थानांच्या आधारे त्यांच्या संबंधांचे मूल्यांकन करते. संबंधाची ताकद ग्रहांमधील कोनीय संबंधावर अवलंबून असते.',
    bn: 'ভৃগু নন্দী নাড়ী সিস্টেম গ্রহদের ভাব অবস্থানের উপর ভিত্তি করে তাদের সম্পর্ক মূল্যায়ন করে। সংযোগের শক্তি গ্রহদের মধ্যে কৌণিক সম্পর্কের উপর নির্ভর করে।',
    te: 'భృగు నంది నాడి వ్యవస్థ గ్రహాల భావ స్థానాల ఆధారంగా వారి సంబంధాలను అంచనా వేస్తుంది. సంబంధ బలం గ్రహాల మధ్య కోణీయ సంబంధంపై ఆధారపడి ఉంటుంది.',
    ta: 'பிருகு நந்தி நாடி அமைப்பு கிரகங்களின் பாவ நிலைகளின் அடிப்படையில் அவற்றின் உறவுகளை மதிப்பீடு செய்கிறது. இணைப்பின் வலிமை கிரகங்களுக்கிடையிலான கோண உறவைப் பொறுத்தது.',
    gu: 'ભૃગુ નંદી નાડી પ્રણાલી ગ્રહોના ભાવ સ્થાનોના આધારે તેમના સંબંધોનું મૂલ્યાંકન કરે છે. સંબંધની શક્તિ ગ્રહો વચ્ચેના કોણીય સંબંધ પર આધાર રાખે છે.',
    pa: 'ਭ੍ਰਿਗੁ ਨੰਦੀ ਨਾੜੀ ਪ੍ਰਣਾਲੀ ਗ੍ਰਹਿਆਂ ਦੇ ਭਾਵ ਸਥਾਨਾਂ ਦੇ ਆਧਾਰ \'ਤੇ ਉਹਨਾਂ ਦੇ ਸੰਬੰਧਾਂ ਦਾ ਮੁਲਾਂਕਣ ਕਰਦੀ ਹੈ। ਸੰਬੰਧ ਦੀ ਤਾਕਤ ਗ੍ਰਹਿਆਂ ਵਿਚਕਾਰ ਕੋਣੀ ਸੰਬੰਧ \'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ।',
  },

