export const getBNNTranslation = (key: string, language: Language): string => {
  // For English, return English directly
  if (language === 'en') return key;
  
  // Check if it's a world language first - check world translations
  if (WORLD_LANGUAGES.includes(language)) {
    const worldTranslation = getWorldTranslation(key, language);
    if (worldTranslation) {
      return `${key} (${worldTranslation})`;
    }
    // No world translation found, return English key
    return key;
  }
  
  // Check all Indian language translation records
  const entry = NADI_YOGA_TRANSLATIONS[key] || 
                BNN_CAREER_TRANSLATIONS[key] || 
                BNN_DHANA_TRANSLATIONS[key] ||
                BNN_PROGRESSION_TRANSLATIONS[key] ||
                YOG_SUMMARY_TRANSLATIONS[key] ||
                PERSONALIZED_TRANSLATIONS[key];
  
  if (!entry) {
    // Check if world translations has this key for fallback
    const worldEntry = WORLD_BNN_TRANSLATIONS[key];
    if (worldEntry) {
      // For Hindi, try to get from entry directly
      if (language === 'hi') {
        return key; // Hindi needs entry from Indian translations
      }
      return key;
    }
    return key;
  }
  
  return getBilingualText(entry, language);
};
